guidance.correct_example:
def calculate(a_value: float, a_multiplier: float = 1.0) -> Result[float]:
    if not isinstance(a_value, (int, float)):
        return Result.failure('Expected number')
    return Result.success(a_value * a_multiplier)

@app.command()
def context(
    task: str = typer.Option('general', '--task'),
    query: str | None = typer.Option(None, '--query', '-q'),
    paths: list[str] = typer.Argument(default=None),
) -> None:
    request = ContextRequest(task=task, query=query, paths=tuple(paths or ()))

